 241	// Trigger: call this when swapping content
 242	function navigate(newHTML) {
 243	  if (!document.startViewTransition) {
 244	    document.querySelector('.main-content').innerHTML = newHTML;
 245	    return;
 246	  }
 247	  document.startViewTransition(() => {
 248	    document.querySelector('.main-content').innerHTML = newHTML;
 249	  });
 250	}
 251	</script>
