 761	  background: rgba(255,255,255,0.4);
 762	  transform: scale(0);
 763	  animation: ripple-anim 0.6s ease-out;
 764	  pointer-events: none;
 765	}
 766	
 767	@keyframes ripple-anim {
 768	  to { transform: scale(4); opacity: 0; }
 769	}
 770	</style>
 771	
 772	<script>
 773	function ripple(e) {
 774	  const btn = e.currentTarget;
 775	  const c = document.createElement('span');
 776	  c.classList.add('ripple-circle');
 777	  const r = btn.getBoundingClientRect();
 778	  const d = Math.max(r.width, r.height);
 779	  c.style.width = c.style.height = d + 'px';
 780	  c.style.left = (e.clientX - r.left - d/2) + 'px';
 781	  c.style.top = (e.clientY - r.top - d/2) + 'px';
 782	  btn.appendChild(c);
 783	  c.addEventListener('animationend', () => c.remove());
 784	}
 785	</script>
 786	```
